data.schema:
({ _req }) => {
  let { code, queryTime } = _req.query;
  if (!code) {
    code = 1;
  } else {
    code += '_1';
  }
  return [
    {
      "orgCode": code,
      "versionId": queryTime? queryTime.split('-').join('') + 1: 1,
      "label": `集团${code}号`,
      "isLeaf": false,
      "children": []
    }
  ];
}
